import {
  PinInput as PinInputPrimitive,
  usePinInput as usePinInputPrimitive,
  usePinInputContext,
  type UsePinInputProps,
  type UsePinInputReturn,
} from '@ark-ui/solid/pin-input';
import { clsx } from 'clsx';
import { children, For, splitProps } from 'solid-js';
import type { ComponentProps } from 'solid-js';
import { SeparatorMarkIcon } from '@/lib/moduix/icons/ui';
import styles from './PinInput.module.css';

type PinInputSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type PinInputRootProps = ComponentProps<typeof PinInputPrimitive.Root> & {
  size?: PinInputSize;
};
type PinInputRootProviderProps = ComponentProps<typeof PinInputPrimitive.RootProvider> & {
  size?: PinInputSize;
};

function PinInput(props: PinInputRootProps) {
  const [local, others] = splitProps(props, ['class', 'placeholder', 'size']);

  return (
    <PinInputPrimitive.Root
      placeholder={local.placeholder ?? ''}
      class={clsx(styles.root, local.class)}
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="pin-input-root"
    />
  );
}

function PinInputRootProvider(props: PinInputRootProviderProps) {
  const [local, others] = splitProps(props, ['class', 'size']);

  return (
    <PinInputPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="pin-input-root-provider"
    />
  );
}

function PinInputLabel(props: ComponentProps<typeof PinInputPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <PinInputPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="pin-input-label"
    />
  );
}

function PinInputControl(props: ComponentProps<typeof PinInputPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <PinInputPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="pin-input-control"
    />
  );
}

function PinInputInput(props: ComponentProps<typeof PinInputPrimitive.Input>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <PinInputPrimitive.Input
      class={clsx(styles.input, local.class)}
      {...others}
      data-slot="pin-input-input"
    />
  );
}

function PinInputInputs(props: { class?: string }) {
  const pinInput = usePinInputContext();

  return (
    <For each={pinInput().items}>
      {(index) => <PinInputInput index={index} class={props.class} />}
    </For>
  );
}

function PinInputSeparator(props: ComponentProps<'span'>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <span
      aria-hidden="true"
      class={clsx(styles.separator, local.class)}
      {...others}
      data-slot="pin-input-separator"
    >
      {resolvedChildren() ?? <SeparatorMarkIcon />}
    </span>
  );
}

function usePinInput(props: UsePinInputProps | (() => UsePinInputProps) = {}): UsePinInputReturn {
  return usePinInputPrimitive(() => ({
    placeholder: '',
    ...(typeof props === 'function' ? props() : props),
  }));
}

const PinInputContext = PinInputPrimitive.Context;
const PinInputHiddenInput = PinInputPrimitive.HiddenInput;

export {
  PinInput,
  PinInputContext,
  PinInputControl,
  PinInputHiddenInput,
  PinInputInput,
  PinInputInputs,
  PinInputLabel,
  PinInputRootProvider,
  PinInputSeparator,
  usePinInput,
  usePinInputContext,
};
export type {
  PinInputContextProps,
  PinInputControlProps,
  PinInputHiddenInputProps,
  PinInputInputProps,
  PinInputLabelProps,
  PinInputValueChangeDetails,
  PinInputValueInvalidDetails,
  UsePinInputContext,
  UsePinInputProps,
  UsePinInputReturn,
} from '@ark-ui/solid/pin-input';

export type { PinInputRootProps, PinInputRootProviderProps, PinInputSize };

@layer moduix.components {
  .root {
    --_pin-input-input-size: var(--moduix-size-md);
    --_pin-input-font-size: var(--moduix-text-lg);
    --_pin-input-line-height: var(--moduix-line-height-text-lg);

    display: inline-flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--moduix-spacing-2);
    color: var(--moduix-color-foreground);

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }

    &[data-size='xs'] {
      --_pin-input-input-size: var(--moduix-size-xs);
      --_pin-input-font-size: var(--moduix-text-sm);
      --_pin-input-line-height: var(--moduix-line-height-text-sm);
    }

    &[data-size='sm'] {
      --_pin-input-input-size: var(--moduix-size-sm);
      --_pin-input-font-size: var(--moduix-text-md);
      --_pin-input-line-height: var(--moduix-line-height-text-md);
    }

    &[data-size='lg'] {
      --_pin-input-input-size: var(--moduix-size-lg);
      --_pin-input-font-size: var(--moduix-text-xl);
      --_pin-input-line-height: var(--moduix-line-height-text-xl);
    }

    &[data-size='xl'] {
      --_pin-input-input-size: var(--moduix-size-xl);
      --_pin-input-font-size: var(--moduix-text-2xl);
      --_pin-input-line-height: var(--moduix-line-height-text-2xl);
    }
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .control {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-pin-input-gap, var(--moduix-spacing-2));
  }

  .input {
    box-sizing: border-box;
    flex: none;
    width: var(--moduix-pin-input-input-size, var(--_pin-input-input-size));
    height: var(--moduix-pin-input-input-size, var(--_pin-input-input-size));
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-pin-input-radius, var(--moduix-radius-md));
    padding: 0;
    background-color: var(--moduix-color-background);
    color: inherit;
    font: inherit;
    font-size: var(--_pin-input-font-size);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--_pin-input-line-height);
    text-align: center;
    font-variant-numeric: tabular-nums;
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);

      &:focus-visible {
        outline-color: var(--moduix-color-destructive);
      }
    }
  }

  .separator {
    display: inline-flex;
    flex: none;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    color: var(--moduix-color-muted-foreground);

    & > svg {
      width: 100%;
      height: 100%;
    }
  }
}
